// Placeholder: Extension content script
// Injected into https://x.com/* to mount the floating panel.
// Initial version creates a toggle button that mounts panel.html/panel.js
// Note: The final orchestrated content.js will be generated by build.js
// and will inline all core modules. This file serves as a fallback if
// build.js is not run and for local testing.

async function mountPlaceholder() {
  if (document.getElementById('xcleaner-fab')) return;

  const fab = document.createElement('button');
  fab.id = 'xcleaner-fab';
  fab.textContent = 'XC';
  fab.style.cssText = 'position:fixed;bottom:20px;right:20px;width:52px;height:52px;border-radius:9999px;background:#000;color:#fff;border:none;z-index:99998;cursor:pointer;font-weight:800;';
  fab.setAttribute('aria-label', 'Open XCleaner panel');
  document.body.appendChild(fab);

  fab.addEventListener('click', async () => {
    if (document.getElementById('xcleaner-root')) return;
    const res = await fetch(chrome.runtime.getURL('panel.html'));
    const html = await res.text();
    const container = document.createElement('div');
    container.innerHTML = html;
    document.body.appendChild(container);
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', mountPlaceholder);
} else {
  mountPlaceholder();
}
